ROOT.scriptdef:
SET NOCOUNT ON
DECLARE @ID INT declare @tmpDecl table( Action varchar(10), ID int)
Merge cdn.DefPodNag as trg using (values('JPK_MAG',1,604,0,'',78531,0,7,0,0,0,0,2,2,2,2,0,'2887abb2a664d10b27522e061cb1541e',0,'2019.1.0',2,0,'tns:JPK','xmlns:xsd="http://www.w3.org/2001/XMLSchema" xmlns:xsi="http://www.w3.org/2001/XMLSchema-instance" xmlns:etd="http://crd.gov.pl/xml/schematy/dziedzinowe/mf/2016/01/25/eD/DefinicjeTypy/" xmlns:kck="http://crd.gov.pl/xml/schematy/dziedzinowe/mf/2013/05/23/eD/KodyCECHKRAJOW/" xsi:schemaLocation="http://jpk.mf.gov.pl/wzor/2016/03/09/03093/ https://www.gov.pl/documents/2034621/2182793/Schemat_JPK_MAG(1)_v1-0.xsd/425b566f-23a7-6b37-876f-6e9592200f1d" xmlns:tns="http://jpk.mf.gov.pl/wzor/2016/03/09/03093/"')) as src (DPN_Symbol,DPN_Wersja,DPN_TypPodatku,DPN_Zalacznik,DPN_Nadrzedna,DPN_DataOd,DPN_DataDo,DPN_IloscStron,DPN_Platnosci,DPN_Ksiegowanie,DPN_NrPozIloscPodpoziomow,DPN_ZalacznikOkresDef,DPN_PoczatekOkresu,DPN_KoniecOkresu,DPN_PoczatekPodOkresu,DPN_KoniecPodOkresu,DPN_TypDeklaracji,DPN_SumaKontrolna,DPN_WersjaNadrzednej,DPN_WersjaWewn,DPN_TypUrzedu,DPN_Lp,DPN_XMLTagNazwa,DPN_XMLTagAtrybuty) on (trg.DPN_Symbol=src.DPN_Symbol and trg.DPN_Wersja=src.DPN_Wersja) when matched and (trg.DPN_Symbol<>src.DPN_Symbol or trg.DPN_Wersja<>src.DPN_Wersja or trg.DPN_TypPodatku<>src.DPN_TypPodatku or trg.DPN_Zalacznik<>src.DPN_Zalacznik or trg.DPN_Nadrzedna<>src.DPN_Nadrzedna or trg.DPN_DataOd<>src.DPN_DataOd or trg.DPN_DataDo<>src.DPN_DataDo or trg.DPN_IloscStron<>src.DPN_IloscStron or trg.DPN_Platnosci<>src.DPN_Platnosci or trg.DPN_Ksiegowanie<>src.DPN_Ksiegowanie or trg.DPN_NrPozIloscPodpoziomow<>src.DPN_NrPozIloscPodpoziomow or trg.DPN_ZalacznikOkresDef<>src.DPN_ZalacznikOkresDef or trg.DPN_PoczatekOkresu<>src.DPN_PoczatekOkresu or trg.DPN_KoniecOkresu<>src.DPN_KoniecOkresu or trg.DPN_PoczatekPodOkresu<>src.DPN_PoczatekPodOkresu or trg.DPN_KoniecPodOkresu<>src.DPN_KoniecPodOkresu or trg.DPN_TypDeklaracji<>src.DPN_TypDeklaracji or trg.DPN_SumaKontrolna<>src.DPN_SumaKontrolna or trg.DPN_WersjaNadrzednej<>src.DPN_WersjaNadrzednej or