ednej,src.DPN_WersjaWewn,src.DPN_TypUrzedu,src.DPN_Lp,src.DPN_XMLTagNazwa,src.DPN_XMLTagAtrybuty)
select top 1 @ID = ID from @tmpDecl; if isnull(@ID,0)=0 return;
select * into #DefPodElem from cdn.DefPodElem where DPE_DPNID = @ID; delete from cdn.DefPodElemKolumny where DPK_DPNID = @ID; delete from cdn.DefPodElem where DPE_DPNID = @ID;
